#!/usr/bin/env bash
# kaiyaku — clj/bb test suite (ADR-2606160842 py->clj port wave). Auto-wired into the fleet
# green-check; runs all cljc test namespaces via babashka from the repo root.
set -euo pipefail
cd "$(dirname "$0")/../.."
exec bb -e '(require (quote clojure.test) (quote kaiyaku.methods.test-datom-emit) (quote kaiyaku.tests.test-analyze) (quote kaiyaku.tests.test-handoff) (quote kaiyaku.tests.test-meisai-ingest) (quote kaiyaku.tests.test-kotoba) (quote kaiyaku.tests.test-plan) (quote kaiyaku.tests.test-driver) (quote kaiyaku.tests.test-catalog) (quote kaiyaku.tests.test-issue-capability) (quote kaiyaku.tests.test-receipt) (quote kaiyaku.tests.test-karakuri-bridge) (quote kaiyaku.tests.test-pipeline) (quote kaiyaku.tests.test-manifest) (quote kaiyaku.tests.test-maturity) (quote kaiyaku.tests.test-audit) (quote kaiyaku.tests.test-charter-invariants) (quote kaiyaku.tests.test-cap))(let [r (apply clojure.test/run-tests (quote [kaiyaku.methods.test-datom-emit kaiyaku.tests.test-analyze kaiyaku.tests.test-handoff kaiyaku.tests.test-meisai-ingest kaiyaku.tests.test-kotoba kaiyaku.tests.test-plan kaiyaku.tests.test-driver kaiyaku.tests.test-catalog kaiyaku.tests.test-issue-capability kaiyaku.tests.test-receipt kaiyaku.tests.test-karakuri-bridge kaiyaku.tests.test-pipeline kaiyaku.tests.test-manifest kaiyaku.tests.test-maturity kaiyaku.tests.test-audit kaiyaku.tests.test-charter-invariants kaiyaku.tests.test-cap]))](System/exit (if (zero? (+ (:fail r) (:error r))) 0 1)))'
